// === Tab: mySketch ===
let num;
let cs;
let paletteSelected;
let paletteSelected1;
let paletteSelected2;

function windowResized() {
	//setSeeds();
	cs = min(windowHeight, windowWidth);
	resizeCanvas(cs, cs);
	resetAndRestart() 
}

function resetAndRestart() {
	randomSeed(num);
	noiseSeed(num);
	////texture----------------------------------
	pg = createGraphics(width, height)
	pg.noStroke();
	let particle_count = floor((cs * cs) * 0.08);
	pg.randomSeed(num);

	for (let i = 0; i < particle_count; i++) {
		let x = pg.random(width);
		let y = pg.random(height);
		let n = noise(x * 0.01, y * 0.01) * ((cs + cs) / 2 * 0.002);
		pg.fill(255, 70);
		pg.ellipse(x, y, n, n);
	}

}

function setup() {

	cs = min(windowHeight, windowWidth);
	createCanvas(cs, cs);
	//setSeeds();
	//pixelDensity(2)
	rectMode(CENTER)
	angleMode(DEGREES);
	num = random(100000);
	paletteSelected = random(palettes);
	paletteSelected1 = random(palettes);
	paletteSelected2 = random(palettes);
       	shuffle(paletteSelected, true)
resetAndRestart() 
}

function draw() {
	randomSeed(num);
	background(paletteSelected[0]);

	tile();
	image(pg, 0, 0)
//	triggerPreview();
}

function tile() {
	let count = 10;
	let w = width / count;
	let mu = (count * count);
	let munum = floor(random(mu));

	let cou = 0;
	for (var j = 0; j < count; j++) {
		for (var i = 0; i < count; i++) {
			if (cou == munum) {
				ghost(w / 2 + i * w, w / 2 + j * w, w * 0.42, 1)
			} else {
				shape(w / 2 + i * w, w / 2 + j * w, w * 0.5, floor(random(5, 12)), random(6.0))
			}
			cou++;
		}
	}
}

function shape(x, y, r, nums, curveVal) {
	push();
	translate(x, y);
	strokeWeight(cs * 0.001)
	if(random()<0.7){
	gradient(r)
	}else{
	fill(randomCol())
	}

	let pts = [];
	for (let i = 0; i < 360; i += (Math.max(0.001, Math.abs(360 / nums)) || 1)) {
		let radius = r * random(0.8, 1.1);
		let cx = radius * cos(i);
		let cy = radius * sin(i);
		let angle = atan2(cy, cx) + random(-15, 15)
		let pos = createVector(cx, cy);
		let ankerLength = (r / nums) * curveVal;
		let anchor1 = p5.Vector.fromAngle(radians(angle - 90), ankerLength);
		let anchor2 = p5.Vector.fromAngle(radians(angle + 90), ankerLength);
		let ankerP1 = p5.Vector.add(pos, anchor1);
		let ankerP2 = p5.Vector.add(pos, anchor2);
		pts.push({
			pos,
			ankerP1,
			ankerP2
		});
	}
noStroke();
	beginShape();
	for (let i = 0; i < pts.length; i++) {
		let points = pts[i];
		let next = pts[(i + 1) % pts.length];
		vertex(points.pos.x, points.pos.y);
		bezierVertex(points.ankerP2.x, points.ankerP2.y, next.ankerP1.x, next.ankerP1.y, next.pos.x, next.pos.y);
	}
	endShape(CLOSE);
	fill(250)
	let leye = -r * 0.3;
	let reye = r * 0.3;
	let dir = random(-r * 0.05, r * 0.05)
	let eyesize = r * random(0.3, 0.4);
	let blackeyeSize = r * random(0.15, 0.25);
	translate(r * random(-0.1, 0.1), r * random(-0.1, 0.1))
	ellipse(leye, 0, eyesize)
	ellipse(reye, 0, eyesize)

	let c = color(randomCol())
	colorMode(HSB, 360, 100, 100, 100)
	noStroke()
	let hsbc = color(hue(window.color(c)), saturation(window.color(c)), brightness(window.color(c)) - 10);
	fill(hsbc)
	ellipse(leye + dir, 0, blackeyeSize)
	ellipse(reye + dir, 0, blackeyeSize)
	pop();
}


function ghost(x, y, w, ran) {
	let randsuso = 3;
	let sheetsCol = "#f4f1de";
	strokeWeight(cs * 0.001)
stroke(randomCol())
	let hW = w;
	let hH = w;
	let susonum = 3
	push();
	translate(x, y);

	//leg_shadow-----
	push();
	beginShape();
	vertex(-hW * 0.95, 0);
	vertex(hW * 0.95, 0);
	for (let i = hW; i > -hW + 1; i -= 1) {
		let y = hH + (hH / 10) * sin(i * susonum * 360 / (hW * 2) + randsuso);
		vertex(i, y);
	}
	vertex(-hW, hH);
	endShape();
	pop();
	//ghost_body-----
	push();

	fill(sheetsCol);
	beginShape();
	vertex(hW, 0);
	bezierVertex(hW * 1.1, -hH * 1.35, -hW * 1.1, -hH * 1.35, -hW, 0);
	vertex(-hW, hH);
	for (let i = -hW; i < hW + 1; i += 1) {
		let y = hH + (hH / 10) * sin((i * susonum * 360 / (hW * 2)) - randsuso);
		vertex(i, y);
	}
	vertex(hW, 0);
	endShape();
	pop();

	//eye
	push();
	noStroke();
	fill(255)
	let leye = -w * 0.37;
	let reye = w * 0.37;
	let dir = random(-w * 0.05, w * 0.05)
	let eyesize = w * random(0.4, 0.45);
	let blackeyeSize = w * random(0.25, 0.3);
	translate(w * random(-0.1, 0.1), -(w * 0.15) + w * random(-0.1, 0.1))
	ellipse(leye, 0, eyesize)
	ellipse(reye, 0, eyesize)

	fill(51)

	ellipse(leye + dir, 0, blackeyeSize)
	ellipse(reye + dir, 0, blackeyeSize)


	pop();
	pop();
}


function gradient(r) {
	col1 = color(random(paletteSelected1));
	col1.setAlpha(30)
	col2 = random(paletteSelected2);

	noStroke();
	let gradientFill = drawingContext.createLinearGradient(
		0,
		-r,
		0,
		r
	);
	gradientFill.addColorStop(0, color(col1));
	gradientFill.addColorStop(1, color(col2));
	drawingContext.fillStyle = gradientFill;
}

function randomCol() {
	let randoms = int(random(1, paletteSelected.length));
	return color(paletteSelected[randoms]);
}
let palettes = [
	["#3c4cad", "#5FB49C", "#e8a49c"],
	["#1c3560", "#ff6343", "#f2efdb", "#fea985"],
	["#e0d7c5", "#488a50", "#b59a55", "#bf5513", "#3b6fb6", "#4f3224", "#9a7f6e"],
